INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','register-variation','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"register-variation","title":"Formal and informal grammar; British and American usage","level":"C1","order":67,"summary":"Recognise standard variation and choose a form that suits the audience rather than treating every difference as an error.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Contractions and formality","Standard varieties differ","Speech leaves more recoverable material unstated","Grammar supports a purpose"],"rules":[{"title":"Contractions and formality","explanation":"Contractions are normal in speech and much informal writing. Full forms can suit a formal notice or create emphasis. A contraction may be ambiguous until its complement is read: she’s can mean she is or she has; she’d can mean she had or she would.","pattern":"She’s **working** = she **is** working. / She’s **finished** = she **has** finished.","commonMistakes":["She’s finished can also mean she is finished in a different context. Read the full sentence rather than expanding mechanically."],"examples":["Expand “she’s” in “She’s preparing the visitor guide right now.” → **she is**","Expand “she’s” in “She’s restoring the old portrait right now.” → **she is**"],"skill":"form"},{"title":"Standard varieties differ","explanation":"British and American English share the central grammar system but differ in some preferences. British English often favours present perfect with just and already; American English also commonly uses past simple. Collective-noun agreement and some prepositions vary.","pattern":"I’ve just eaten. / I just ate.","commonMistakes":["A form common in another standard variety is not automatically an error. Practice questions specify a variety when the distinction matters."],"examples":["Expand “she’d” in “She’d prepare the visitor guide if she had time.” → **she would**","Expand “she’d” in “She’d restore the old portrait if she had time.” → **she would**"],"skill":"meaning"},{"title":"Speech leaves more recoverable material unstated","explanation":"Informal speech often uses ellipsis and short responses because the context is shared. Formal standalone writing usually needs clearer reference and fuller sentence structure. The choice depends on audience and purpose, not on one style being universally superior.","pattern":"Want a hand? → **Do you want** a hand?","commonMistakes":["A conversational fragment can be effective in dialogue while being unsuitable as an isolated formal report sentence."],"examples":["Rewrite “We won’t prepare the visitor guide today” using the full negative form. → **We will not prepare the visitor guide today.**","Rewrite “We won’t restore the old portrait today” using the full negative form. → **We will not restore the old portrait today.**"],"skill":"contrast"},{"title":"Grammar supports a purpose","explanation":"Polite modal questions, hedging and impersonal passives can soften a claim or request. Active clauses can make responsibility clearer. Use those tools deliberately: clarity is more important than adding complicated structures. Respect dialect differences while learning the standard forms appropriate to a particular setting.","pattern":"Could you check this? / We suggest that the team review it.","commonMistakes":["This course gives broad standard-English practice, not an exhaustive catalogue of dialect grammar or a certificate of fluency."],"examples":["Choose a standard polite modal request asking someone to prepare the visitor guide. → **Could you prepare the visitor guide, please?**","Choose a standard polite modal request asking someone to restore the old portrait. → **Could you restore the old portrait, please?**"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-varieties"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"4ed79467-23da-5c22-abcb-946052153ba8","topicSlug":"register-variation","level":"C1","prompt":"Expand “she’s” in “She’s preparing the visitor guide right now.”","choices":[{"id":"A","text":"she does"},{"id":"B","text":"she is"},{"id":"C","text":"she has"},{"id":"D","text":"she was"}],"answerId":"B","hint":"Use the following **-ing form** to identify the auxiliary.","explanation":"Before the active -ing form **preparing**, she’s expands to **she is**.","keywords":["expand-progressive-contraction"],"skill":"expand-progressive-contraction","contextKey":"register-variation-1","fingerprint":"6029a93a2f256355a42bbae12e0927e78a190ff005eea7caa83a459099c31e39","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-varieties"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Use the following **-ing form** to identify the auxiliary.","Before the active -ing form **preparing**, she’s expands to **she is**.","Choose **she is**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"She’s does not contract she does.","B":"Before the active -ing form **preparing**, she’s expands to **she is**.","C":"Has alone cannot precede this -ing form.","D":"She’s does not contract she was."}}},{"id":"c46be5aa-7f21-5f0d-ae87-9e50a9379026","topicSlug":"register-variation","level":"C1","prompt":"Expand “she’d” in “She’d prepare the visitor guide if she had time.”","choices":[{"id":"A","text":"she would"},{"id":"B","text":"she had"},{"id":"C","text":"she did"},{"id":"D","text":"she should"}],"answerId":"A","hint":"The following **base verb** and conditional result point to would.","explanation":"The base verb prepare and hypothetical condition identify **she would**.","keywords":["expand-would-contraction"],"skill":"expand-would-contraction","contextKey":"register-variation-1","fingerprint":"c1dddaf0d15fb4377fb9bfa24acf244572d9d3e874483200a75939e061c99a65","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-varieties"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The following **base verb** and conditional result point to would.","The base verb prepare and hypothetical condition identify **she would**.","Choose **she would**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The base verb prepare and hypothetical condition identify **she would**.","B":"Had would need a participle or another complement, not this base verb in the conditional result.","C":"She’d does not contract she did.","D":"She’d does not contract she should."}}},{"id":"46be4054-0654-5ac6-ab8a-16e501da996d","topicSlug":"register-variation","level":"C1","prompt":"Rewrite “We won’t prepare the visitor guide today” using the full negative form.","choices":[{"id":"A","text":"We would not prepare the visitor guide today."},{"id":"B","text":"We will not to prepare the visitor guide today."},{"id":"C","text":"We will not prepared the visitor guide today."},{"id":"D","text":"We will not prepare the visitor guide today."}],"answerId":"D","hint":"Expand the contraction while **preserving the original modal and meaning**.","explanation":"**Won’t** expands to **will not**; keep the base verb unchanged.","keywords":["formal-negative"],"skill":"formal-negative","contextKey":"register-variation-1","fingerprint":"f02d5029cca52b052bf639d33209633d1b059d4d229c833b753cd96c0c520d83","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-varieties"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Expand the contraction while **preserving the original modal and meaning**.","**Won’t** expands to **will not**; keep the base verb unchanged.","Choose **We will not prepare the visitor guide today.**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Would not changes the modal and meaning; it does not expand won’t.","B":"Will not takes an infinitive without to.","C":"The verb after will not must remain base form.","D":"**Won’t** expands to **will not**; keep the base verb unchanged."}}},{"id":"32ddb758-0b21-578c-ad4d-36d3e5edfa99","topicSlug":"register-variation","level":"C1","prompt":"Choose a standard polite modal request asking someone to prepare the visitor guide.","choices":[{"id":"A","text":"Do could you prepare the visitor guide, please?"},{"id":"B","text":"Could you prepare the visitor guide, please?"},{"id":"C","text":"Could you to prepare the visitor guide, please?"},{"id":"D","text":"Could you prepared the visitor guide, please?"}],"answerId":"B","hint":"Use the **modal question** pattern to make a polite request.","explanation":"**Could you + base verb** is a standard polite request.","keywords":["polite-request-register"],"skill":"polite-request-register","contextKey":"register-variation-1","fingerprint":"4d903fd1cf0542648bde296e13e560cdfc9df845fda2af4e2d39032915e2d52f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-varieties"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Use the **modal question** pattern to make a polite request.","**Could you + base verb** is a standard polite request.","Choose **Could you prepare the visitor guide, please?**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Could forms its own question; do-support is not added.","B":"**Could you + base verb** is a standard polite request.","C":"Could takes a bare infinitive without to.","D":"The main verb after could remains base, not past."}}},{"id":"126541fa-26e1-5f93-aa70-201d93885407","topicSlug":"register-variation","level":"C1","prompt":"Expand “she’s” in “She’s restoring the old portrait right now.”","choices":[{"id":"A","text":"she does"},{"id":"B","text":"she is"},{"id":"C","text":"she has"},{"id":"D","text":"she was"}],"answerId":"B","hint":"Use the following **-ing form** to identify the auxiliary.","explanation":"Before the active -ing form **restoring**, she’s expands to **she is**.","keywords":["expand-progressive-contraction"],"skill":"expand-progressive-contraction","contextKey":"register-variation-2","fingerprint":"e3b75decc2d519d1f46fb5016e1a4961b71ea6c705d1032a71bfbdf467f00d09","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-varieties"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Use the following **-ing form** to identify the auxiliary.","Before the active -ing form **restoring**, she’s expands to **she is**.","Choose **she is**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"She’s does not contract she does.","B":"Before the active -ing form **restoring**, she’s expands to **she is**.","C":"Has alone cannot precede this -ing form.","D":"She’s does not contract she was."}}},{"id":"04f48cdc-47a8-529a-a998-99b0c132062b","topicSlug":"register-variation","level":"C1","prompt":"Expand “she’d” in “She’d restore the old portrait if she had time.”","choices":[{"id":"A","text":"she should"},{"id":"B","text":"she would"},{"id":"C","text":"she had"},{"id":"D","text":"she did"}],"answerId":"B","hint":"The following **base verb** and conditional result point to would.","explanation":"The base verb restore and hypothetical condition identify **she would**.","keywords":["expand-would-contraction"],"skill":"expand-would-contraction","contextKey":"register-variation-2","fingerprint":"d1cbf35e57fb591d6d30e57